package com.taly.toss.home

import android.content.Context
import android.graphics.*
import android.graphics.drawable.Drawable
import android.view.KeyEvent
import android.view.View
import android.widget.Toast
import kotlin.math.min

class TossHomeView(context:Context,private val youtubeIcon:Drawable?=null,private val onYouTube:()->Result<Unit>,private val onHdmi:()->Result<Unit>,private val onCinema:()->Result<Unit>,private val onCast:()->Result<Unit>,private val onFiles:()->Result<Unit>,private val onApps:()->Unit,private val onMusic:()->Result<Unit>,private val onBrowser:()->Result<Unit>,private val onProjector:()->Unit,private val onSettings:()->Unit):View(context){
    private val p=Paint(Paint.ANTI_ALIAS_FLAG);private val t=Paint(Paint.ANTI_ALIAS_FLAG);private val b=Paint(Paint.ANTI_ALIAS_FLAG).apply{typeface=Typeface.DEFAULT_BOLD};private val purple=Color.rgb(151,91,255);private val bright=Color.rgb(190,148,255);private val white=Color.rgb(246,244,251);private val muted=Color.rgb(177,171,191);private val shortcuts=listOf("Cinema","YouTube","HDMI","Espelhar","Arquivos","Apps","Música","Navegador");private val recommendations=listOf("Filmes","Séries","Sua biblioteca","Recentes");private var selected=1
    init{isFocusable=true;isFocusableInTouchMode=true;requestFocus()}
    override fun onDraw(c:Canvas){val s=min(width/1280f,height/720f);c.save();c.translate((width-1280*s)/2,(height-720*s)/2);c.scale(s,s);p.shader=LinearGradient(0f,0f,1280f,720f,intArrayOf(Color.rgb(22,11,37),Color.rgb(10,8,16),Color.rgb(6,6,10)),floatArrayOf(0f,.48f,1f),Shader.TileMode.CLAMP);c.drawRect(0f,0f,1280f,720f,p);p.shader=null;t.color=muted;t.textSize=18f;t.textAlign=Paint.Align.RIGHT;c.drawText("Wi-Fi   •   TOSS 0.1",1220f,48f,t);hero(c);shortcuts(c);recommendations(c);pill(c,RectF(64f,654f,207f,700f),"Projetor",selected==13);pill(c,RectF(1052f,654f,1216f,700f),"Ajustes",selected==14);c.restore()}
    private fun hero(c:Canvas){val r=RectF(64f,70f,1216f,292f);card(c,r,selected==0,true);t.textAlign=Paint.Align.LEFT;t.color=bright;t.textSize=17f;c.drawText("CONTINUAR ASSISTINDO",98f,112f,t);b.color=white;b.textSize=38f;c.drawText("Cinema TOSS",98f,164f,b);t.color=muted;t.textSize=20f;c.drawText("Abra seus vídeos e continue de onde parou",98f,200f,t);p.color=purple;c.drawRoundRect(RectF(98f,242f,286f,248f),3f,3f,p);p.color=Color.argb(185,151,91,255);c.drawCircle(1110f,181f,38f,p);p.color=white;c.drawPath(Path().apply{moveTo(1101f,163f);lineTo(1101f,199f);lineTo(1128f,181f);close()},p)}
    private fun shortcuts(c:Canvas){b.color=white;b.textSize=21f;b.textAlign=Paint.Align.LEFT;c.drawText("Acesso rápido",64f,335f,b);val gap=12f;val w=(1152f-gap*7)/8f;shortcuts.forEachIndexed{i,label->val left=64f+i*(w+gap);val r=RectF(left,354f,left+w,444f);card(c,r,selected==i+1);if(i==1&&youtubeIcon!=null){val d=youtubeIcon;val size=42;d.setBounds((r.centerX()-size/2).toInt(),362,(r.centerX()+size/2).toInt(),404);d.draw(c)}else glyph(c,r.centerX(),383f,i,selected==i+1);t.textAlign=Paint.Align.CENTER;t.textSize=16f;t.color=white;c.drawText(label,r.centerX(),425f,t)}}
    private fun glyph(c:Canvas,x:Float,y:Float,i:Int,f:Boolean){p.style=Paint.Style.STROKE;p.strokeWidth=2.4f;p.color=if(f)bright else Color.rgb(193,183,211);when(i){0->{c.drawRoundRect(RectF(x-15,y-11,x+15,y+11),5f,5f,p);c.drawPath(Path().apply{moveTo(x-3,y-6);lineTo(x-3,y+6);lineTo(x+7,y);close()},p)};2->c.drawRect(x-15,y-10,x+15,y+10,p);3->{c.drawArc(RectF(x-15,y-15,x+15,y+15),215f,110f,false,p);c.drawArc(RectF(x-9,y-9,x+9,y+9),215f,110f,false,p)};4->c.drawRect(x-15,y-10,x+15,y+11,p);5->for(xx in listOf(-9f,9f))for(yy in listOf(-9f,9f))c.drawRoundRect(RectF(x+xx-5,y+yy-5,x+xx+5,y+yy+5),2f,2f,p);6->{c.drawCircle(x-7,y+8,6f,p);c.drawCircle(x+10,y+4,6f,p);c.drawLine(x-1,y+8,x-1,y-12,p);c.drawLine(x-1,y-12,x+16,y-16,p)};else->c.drawCircle(x,y,14f,p)};p.style=Paint.Style.FILL}
    private fun recommendations(c:Canvas){b.color=white;b.textSize=21f;b.textAlign=Paint.Align.LEFT;c.drawText("Para você",64f,492f,b);recommendations.forEachIndexed{i,label->val left=64f+i*288f;val r=RectF(left,511f,left+270f,624f);card(c,r,selected==i+9);p.shader=LinearGradient(r.left,r.top,r.right,r.bottom,Color.argb(80,151,91,255),Color.argb(5,151,91,255),Shader.TileMode.CLAMP);c.drawRoundRect(r,18f,18f,p);p.shader=null;t.color=white;t.textSize=18f;t.textAlign=Paint.Align.LEFT;c.drawText(label,r.left+18f,r.bottom-20f,t)}}
    private fun pill(c:Canvas,r:RectF,label:String,f:Boolean){p.color=if(f)Color.rgb(91,46,160)else Color.rgb(25,21,34);c.drawRoundRect(r,23f,23f,p);t.textAlign=Paint.Align.CENTER;t.color=white;t.textSize=17f;c.drawText(label,r.centerX(),r.centerY()+6,t)}
    private fun card(c:Canvas,r:RectF,f:Boolean,hero:Boolean=false){p.color=if(f)Color.rgb(55,34,81)else if(hero)Color.rgb(18,15,27)else Color.rgb(27,22,39);c.drawRoundRect(r,if(hero)28f else 18f,if(hero)28f else 18f,p);if(f){p.style=Paint.Style.STROKE;p.strokeWidth=2.5f;p.color=bright;c.drawRoundRect(r,if(hero)28f else 18f,if(hero)28f else 18f,p);p.style=Paint.Style.FILL}}
    override fun onKeyDown(k:Int,e:KeyEvent?):Boolean{val old=selected;selected=when(k){KeyEvent.KEYCODE_DPAD_UP->when(selected){in 1..8->0;in 9..12->((selected-9)*2+1).coerceAtMost(8);13,14->9;else->selected};KeyEvent.KEYCODE_DPAD_DOWN->when(selected){0->1;in 1..8->9+((selected-1)/2).coerceAtMost(3);in 9..12->if(selected<=10)13 else 14;else->selected};KeyEvent.KEYCODE_DPAD_LEFT->when(selected){in 2..8->selected-1;in 10..12->selected-1;14->13;else->selected};KeyEvent.KEYCODE_DPAD_RIGHT->when(selected){in 1..7->selected+1;in 9..11->selected+1;13->14;else->selected};KeyEvent.KEYCODE_DPAD_CENTER,KeyEvent.KEYCODE_ENTER->{activate();return true};else->return super.onKeyDown(k,e)};if(old!=selected)invalidate();return true}
    private fun activate(){val result:Result<Unit>?=when(selected){0,1,9,10->onCinema();2->onYouTube();3->onHdmi();4->onCast();5,11,12->onFiles();6->{onApps();null};7->onMusic();8->onBrowser();13->{onProjector();null};14->{onSettings();null};else->null};result?.onFailure{Toast.makeText(context,it.message?:"Ação indisponível",Toast.LENGTH_SHORT).show()}}
}
